import {sceneryProfiles} from './scenery-profile.js?v=84';
export function mountBasinEditor(body,{onChange,onBack,onSound}){
 let selected=7,profileId='kofu';const profile=()=>sceneryProfiles().find(p=>p.id===profileId);const basinProfile=()=>profile().rows;
 body.innerHTML='<header class="shell-heading"><small>SCENERY PROFILE / ALL LINES</small><h1 id="sceneryHeading">沿線景観 · 甲府盆地</h1></header><select class="basin-profile-select" aria-label="景観を見る路線"></select><p class="basin-note">建物・森林・農地と標高から自動判定。駅間も補間し、0～100の景観指数で表示します。</p><div class="basin-legend"><span>━ 建物の多さ</span><span>━ 緑の多さ</span><small>0：少ない　100：多い</small></div><svg class="basin-chart" viewBox="0 0 1420 360" role="group" aria-label="駅別 建物と緑の密度グラフ"></svg><div class="basin-controls"><button data-prev>◀</button><strong id="basinStation"></strong><button data-next>▶</button><div class="auto-density"><span>建物 <output id="buildingOutput"></output></span><span>緑 <output id="greenOutput"></output></span><small id="autoSource"></small></div></div><p class="basin-help">駅を選んで自動判定の結果を見る · 11駅ずつ表示 · © OpenStreetMap contributors · 地形：国土地理院</p><div class="shell-actions"><button data-back>◀ オプションへ</button><span class="auto-badge">自動判定 ON · 上下両方向に適用</span></div>';
 const svg=body.querySelector('svg'),select=body.querySelector('select');select.innerHTML=sceneryProfiles().map(p=>`<option value="${p.id}">${p.name}</option>`).join('');select.value=profileId;select.onchange=()=>{profileId=select.value;selected=0;draw();onSound?.('cursor');};
 function draw(){
  const all=basinProfile(),start=Math.floor(selected/11)*11,rows=all.slice(start,start+11),x=i=>65+i*1290/Math.max(1,rows.length-1),y=v=>270-v*2.25;body.querySelector('#sceneryHeading').textContent='沿線景観 · '+profile().name;
  svg.innerHTML=[0,25,50,75,100].map(v=>`<path d="M65 ${y(v)}H1375" class="grid"/><text x="45" y="${y(v)+6}" text-anchor="end">${v}</text>`).join('')+['building','green'].map(k=>`<path class="area ${k}" d="M65 270 ${rows.map((r,i)=>`L${x(i)} ${y(r[k])}`).join(' ')} L${x(rows.length-1)} 270Z"/><polyline class="line ${k}" points="${rows.map((r,i)=>`${x(i)},${y(r[k])}`).join(' ')}"/>`).join('')+`<path class="selection" d="M${x(selected-start)} 35V285"/>`+rows.map((r,i)=>`<g data-station="${i+start}" tabindex="0" role="button" aria-label="${r.name} 建物${r.building} 緑${r.green}"><rect x="${x(i)-56}" y="30" width="112" height="315" fill="transparent"/>${['building','green'].map(k=>`<circle class="${k}" cx="${x(i)}" cy="${y(r[k])}" r="${i+start===selected?8:5}"/>`).join('')}<text style="font-size:${r.name.length>7?13:17}px" x="${x(i)}" y="310" text-anchor="middle" class="${i+start===selected?'active':''}">${r.name}</text></g>`).join('');
  svg.querySelectorAll('[data-station]').forEach(g=>{g.onclick=()=>choose(Number(g.dataset.station));g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(Number(g.dataset.station));}};});
  const row=all[selected];body.querySelector('#basinStation').textContent=row.name;body.querySelector('#basinStation').style.fontSize=row.name.length>7?'18px':'29px';
  for(const k of ['building','green'])body.querySelector(`#${k}Output`).textContent=Math.round(row[k]);body.querySelector('#autoSource').textContent=row.source==='fictional-landuse'?'人里・森林などの地域設定から自動判定':`駅周辺600 m · 地図で分類 ${Math.round((row.coverage??0)*100)}% · 残りは周辺地形から推定`;
 }
 function choose(i){selected=(i+basinProfile().length)%basinProfile().length;onSound?.('cursor');draw();}
 body.querySelector('[data-prev]').onclick=()=>choose(selected-1);body.querySelector('[data-next]').onclick=()=>choose(selected+1);
 body.querySelector('[data-back]').onclick=onBack;draw();
}
